function showModal(n){$(n).modal("show")}class Sidebar{collapseExpandSidebar(){let n=window.matchMedia("only screen and (max-device-width: 767px)").matches;if(n)$("#sidebarCollapse").on("click",function(){$("#sidebar").toggleClass("expand-mobile")});else $("#sidebarCollapse").on("click",function(){$("#sidebar").toggleClass("active")})}activeLink(){var n=location.pathname;$(".vertical-nav-menu li a").each(function(){var t=$(this);t.attr("href")===n&&t.addClass("active")})}}let sideBar=new Sidebar;sideBar.collapseExpandSidebar();sideBar.activeLink();